93	    public boolean existsByTelephone(String telephone) throws DataAccessException {
94	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.telephone = :telephone");
95	        query.setParameter("telephone", telephone);
96	        return (long) query.getSingleResult() > 0;
97	    }
